 internal static int ReaderTest(string folder){try{var html=File.ReadAllText(Path.Combine(folder,"page.html"));var normal=GanymedeReader.Normalise(html);var doc=GanymedeReader.Parse(normal,"ganymede-2");var index=new QuestInstructionIndex();index.Add(normal,"ganymede-2");var quest=new TougliStep{QuestId="1631",Title="Réponses à tout"};var matches=index.Match(quest);Check(matches.Count>=2,"Correspondance réelle Réponses à tout");Check(matches.Any(x=>x.Details.Contains("Ganymède")),"Instructions réelles présentes");File.WriteAllText(Path.Combine(folder,"ganymede-result.json"),Store.Json.Serialize(new{title=doc.Title,steps=doc.Steps.Count,coordinates=doc.Steps.Count(x=>x.Coordinates!=""),instructionChars=doc.Steps.Sum(x=>x.Details.Length),questBlocks=index.Items.Count,matchedQuest=quest.Title,matchedInstructions=matches.Count}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"GANYMEDE_FAIL.txt"),ex.ToString());return 1;}}
 static void GanymedeTest(Store store,string folder){var guide=new{id=12,name="Guide fictif",web_description="Exemple de test",user=new{name="Auteur fictif"},steps=new[]{new{id=101,name="",order=1,map="Carte de test",pos_x=-3,pos_y=2,web_text="<p>Parlez au personnage fictif.</p><script>alert(1)</script><p>Choisissez la réponse de test.</p>"},new{id=102,name="Étape de test",order=2,map="Carte de test",pos_x=0,pos_y=0,web_text="<p>Instruction inventée.</p>"}}};var json=Store.Json.Serialize(new{props=new{guide=guide}});var html="<html><script type=\"application/json\" data-page=\"app\">"+json+"</script></html>";var raw=GanymedeReader.Normalise(html);var doc=GanymedeReader.Parse(raw,"ganymede-12");Check(doc.Steps.Count==2&&doc.Steps[0].Coordinates=="-3,2"&&doc.Steps[1].Coordinates=="0,0","Coordonnées Ganymède explicites");Check(doc.Steps[0].Details.Contains("réponse de test")&&!doc.Steps[0].Details.Contains("alert"),"Instructions et retrait scripts");Check(doc.Description.Contains("Auteur fictif")&&GanymedeReader.Url(doc.Slug)=="https://ganymede-app.com/guides/12","Attribution et lien source");Check(GanymedeReader.GuideSlug("https://ganymede-app.com/guides/12?page=2")=="ganymede-12","Lien direct guide");bool rejected=false;try{GanymedeReader.GuideSlug("https://evil.example/guides/12");}catch(InvalidDataException){rejected=true;}Check(rejected,"Source arbitraire refusée");rejected=false;try{GanymedeReader.Parse(raw,"ganymede-13");}catch(InvalidDataException){rejected=true;}Check(rejected,"Guide inattendu refusé");var tree="<script data-page=\"app\">"+Store.Json.Serialize(new{props=new{nodes=new[]{new{hidden=0,guides=new{fr=new{id=12,name="Guide fictif"}}}}}})+"</script>";Check(GanymedeReader.Catalogue(tree).Single().Slug=="ganymede-12","Catalogue français public");var character=DofusCompanion.Character(store.Value);string old=character.guide;PersonalWorkflows.Change(store,()=>character.guide=doc.Slug);TougliReader.Cache(store,doc.Slug,raw);var w=new CompanionWindow(store,true);w.Render(Path.Combine(folder,"ganymede.png"));Find<Button>(w.Content as DependencyObject).First(x=>Equals(x.Content,"Terminé →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(DofusCompanion.Find(store.Value,character).done.Count==1,"Validation réelle Ganymède");var restart=new Store(store.Root);var saved=DofusCompanion.Character(restart.Value);Check(DofusCompanion.Find(restart.Value,saved).done.Count==1,"Reprise Ganymède");PersonalWorkflows.Change(store,()=>DofusCompanion.Character(store.Value).guide=old);Check(DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count==1,"Progression Tougli conservée à part");w.Close();}

 static void AssociationTest(Store store,string folder){var c=DofusCompanion.Character(store.Value);var tougli=TougliReader.Parse(Sample,c);var step=tougli.Steps.First(x=>x.QuestId=="10");Func<int,string> sample=id=>Store.Json.Serialize(new{ganymedeGuide=new{id=id,name="Association de test "+id,author="Auteur fictif",description="Exemple",steps=new[]{new{id=201,name="",order=1,map="Carte fictive",pos_x=-1,pos_y=2,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><div><p>Instruction pour la première quête.</p></div></div><div data-type=\"quest-block\" questname=\"Autre quête\"><p>NE PAS ATTRIBUER CETTE INSTRUCTION.</p></div>"},new{id=202,name="",order=2,map="Carte fictive",pos_x=0,pos_y=0,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><p>Suite de la première quête.</p></div>"}}}});
 var index=new QuestInstructionIndex();index.Add(sample(20),"ganymede-20");Check(index.Match(step).Count==2,"Correspondance quête et plusieurs extraits");Check(index.Match(step).All(x=>!x.Details.Contains("NE PAS")),"Instructions d’autre quête exclues");Check(index.Match(new TougliStep{Title="Premiere quete fictive",QuestId="10"}).Count==2,"Accents et casse");Check(index.Match(new TougliStep{Title="Première quête fictiv",QuestId="10"}).Count==0,"Aucune correspondance approximative");Check(index.Match(new TougliStep{Title=step.Title,QuestId=null}).Count==0,"Note Tougli non associée par simple nom");TougliReader.Cache(store,"ganymede-20",sample(20));var p=DofusCompanion.Get(store.Value,c);PersonalWorkflows.Change(store,()=>p.cursor=step.Key);var w=new CompanionWindow(store,true);w.Render(Path.Combine(folder,"tougli-ganymede.png"));Check(Find<TextBlock>(w.Content as DependencyObject).Any(t=>t.Inlines.OfType<System.Windows.Documents.Hyperlink>().Any(h=>Equals(h.Tag,"/travel -1,2"))),"Coordonnée cliquable dans le compagnon indépendant");Check(Find<TextBlock>(w.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."),"Instructions Ganymède intégrées à la quête Tougli");Find<Button>(w.Content as DependencyObject).First(b=>Equals(b.Content,"Instruction →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.Render(Path.Combine(folder,"tougli-ganymede-next.png"));Check(Find<TextBlock>(w.Content as DependencyObject).Any(t=>t.Text=="Suite de la première quête."),"Navigation des sous-instructions réelle");Check(DofusCompanion.Current(store.Value,tougli).Key==step.Key&&DofusCompanion.Find(store.Value,c).done.Count==1,"Instruction suivante ne valide pas la quête Tougli");var restarted=new Store(store.Root);Check(restarted.Value.instructions.cursors.Count==1,"Sous-étape sauvegardée");w.Close();index.Add(sample(21),"ganymede-21");Check(index.Match(step).Select(x=>x.GuideSlug).Distinct().Count()==2,"Sources ambiguës conservées séparément");TougliReader.Cache(store,"ganymede-21",sample(21));var ambiguous=new CompanionWindow(store,true);ambiguous.Render(Path.Combine(folder,"association-choice.png"));Check(!Find<TextBlock>(ambiguous.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."),"Source ambiguë non choisie automatiquement");var select=Find<ComboBox>(ambiguous.Content as DependencyObject).Single();select.SelectedIndex=1;ambiguous.Render(Path.Combine(folder,"association-chosen.png"));Check(Find<TextBlock>(ambiguous.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."||t.Text=="Suite de la première quête."),"Choix de source réel");ambiguous.Close();}
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject parent) where T:DependencyObject {if(parent is T)yield return (T)parent;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);i++)foreach(var item in Find<T>(System.Windows.Media.VisualTreeHelper.GetChild(parent,i)))yield return item;}
 static void InstructionStyleTest(string folder){var store=new Store(Path.Combine(folder,"style-ui"));var c=new DofusCharacter{id="style-player",name="Aventurier",classCode="Sacri",guide="ganymede-99"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;store.Save();string raw=Store.Json.Serialize(new{ganymedeGuide=new{id=99,name="Consignes fictives de validation",author="Auteur fictif",description="Données de test",steps=new[]{new{id=1,name="Instruction",order=1,map="Carte fictive",pos_x=-3,pos_y=2,text="<p>Rendez-vous en [-3,2].</p><p>Parlez à Test-PNJ avec 3 ressources.</p><p>Si vous êtes Iop, ne prenez pas ce chemin.</p>"}}}});TougliReader.Cache(store,c.guide,raw);string before=GanymedeReader.Parse(raw,c.guide).Steps[0].Key;var w=new CompanionWindow(store,true);w.Render(Path.Combine(folder,"instructions-compagnon.png"));Check(Find<TextBlock>(w.Content as DependencyObject).Any(x=>x.Text=="Parle à Test-PNJ avec 3 ressources."),"Réécriture réellement affichée sur Ganymède");Check(Find<TextBlock>(w.Content as DependencyObject).Any(x=>x.Text=="Si vous êtes Iop, ne prenez pas ce chemin."),"Condition conservée à l’écran");Check(Find<TextBlock>(w.Content as DependencyObject).Any(x=>x.Inlines.OfType<System.Windows.Documents.Hyperlink>().Any(h=>Equals(h.Tag,"/travel -3,2"))),"Coordonnées réécrites toujours cliquables");Find<Button>(w.Content as DependencyObject).First(x=>Equals(x.Content,"Texte source")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.Render(Path.Combine(folder,"instructions-source.png"));Check(!store.Value.instructions.companion&&Find<TextBlock>(w.Content as DependencyObject).Any(x=>x.Text.Contains("Parlez à Test-PNJ avec 3 ressources.")),"Bascule réelle vers le texte source");Find<Button>(w.Content as DependencyObject).First(x=>Equals(x.Content,"Style compagnon")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.Render(Path.Combine(folder,"instructions-compagnon-retour.png"));Check(store.Value.instructions.companion&&new Store(store.Root).Value.instructions.companion,"Style conservé après réouverture");Check(GanymedeReader.Parse(TougliReader.Cached(store,c.guide),c.guide).Steps[0].Key==before&&DofusCompanion.Find(store.Value,c)==null,"Source et progression inchangées par la personnalisation");w.Close();}
 static void DofusToolsUiTest(string folder){var store=new Store(Path.Combine(folder,"tools-ui"));var c=new DofusCharacter{id="tool-ui",name="Test UI",guide="parcours-exemple"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;TougliReader.Cache(store,c.guide,Sample);var controller=new CompanionWindow(store,true);var options=new Window{Width=600,Height=750,Resources=controller.Resources};var panel=new StackPanel();var actions=new WrapPanel();DofusToolsUi.Options(panel,actions,store,()=>{},()=>{},CompanionTheme.Ink,CompanionTheme.Muted);panel.Children.Add(actions);options.Content=panel;CompanionWindow.RenderPreview(options,Path.Combine(folder,"overlay-options.png"));Find<Slider>(options.Content as DependencyObject).First().Value=120;Find<Button>(options.Content as DependencyObject).First(b=>Equals(b.Content,"Enregistrer l’overlay")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(new Store(store.Root).Value.dofus.overlay.portrait!=120)throw new Exception("Options UI du compagnon perdues");var step=controller.Current().Steps[0];var notes=new Window{Width=600,Height=750,Resources=controller.Resources};panel=new StackPanel();actions=new WrapPanel();DofusToolsUi.Notes(panel,actions,store,step,()=>{},()=>{},CompanionTheme.Ink,CompanionTheme.Muted);panel.Children.Add(actions);notes.Content=panel;CompanionWindow.RenderPreview(notes,Path.Combine(folder,"quest-preparation.png"));Find<TextBox>(notes.Content as DependencyObject).First().Text="À faire en guilde";Find<Button>(notes.Content as DependencyObject).First(b=>Equals(b.Content,"Enregistrer mes notes")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(DofusTools.Note(new Store(store.Root).Value,step).body!="À faire en guilde")throw new Exception("Notes UI perdues");controller.Show();QuestCaptureAcceptance.Ui(controller,folder,Sample);controller.Close();options.Close();notes.Close();}
