st();var ownHandle=new System.Windows.Interop.WindowInteropHelper(songes).Handle;var ownWindow=new SongesGameWindow{Handle=ownHandle,ProcessId=System.Diagnostics.Process.GetCurrentProcess().Id,Title="Compagnon Dofus · Songes"};Check(!SongesCapture.Valid(ownWindow)&&SongesCapture.Frame(ownWindow)==null,"Capture du compagnon refusée même avec une sélection périmée");Find<Button>(songes.Content as DependencyObject).First(x=>Equals(x.Content,"Actualiser les fenêtres DOFUS")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var gameList=Find<ComboBox>(songes.Content as DependencyObject).First();Check(!gameList.Items.Cast<SongesGameWindow>().Any(x=>x.ProcessId==ownWindow.ProcessId),"La vraie liste de fenêtres exclut le compagnon");gameList.ItemsSource=new[]{ownWindow};gameList.SelectedIndex=0;Find<Button>(songes.Content as DependencyObject).First(x=>Convert.ToString(x.Content).Contains("Activer la détection")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!Find<Button>(songes.Content as DependencyObject).Any(x=>Convert.ToString(x.Content).Contains("Mettre en pause")),"La détection refuse la fenêtre du compagnon");songes.Close();var window=new CompanionWindow(store,true);window.Render(Path.Combine(folder,"overlay.png"));var finish=Find<Button>(window.Content as DependencyObject).First(x=>Equals(x.Content,"Terminé →"));finish.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Bouton réel valider");Check(DofusCompanion.Current(store.Value,doc).Title.Contains("Première quête"),"Navigation réelle");window.Render(Path.Combine(folder,"overlay-next.png"));DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==2,"Validation");DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Annulation");store.Value.dofus.active=b.id;store.Save();Check(DofusCompanion.Find(store.Value,b)==null,"Indépendance personnage");Check(TougliReader.Parse(Sample,b).Steps.Last().Title.Contains("Iop"),"Autre classe");store.Value.dofus.active=a.id;store.Save();var reopened=new Store(store.Root);Check(DofusCompanion.Find(reopened.Value,DofusCompanion.Character(reopened.Value)).done.Count==1,"Reprise sauvegarde");var tmp=Path.Combine(store.Root,"state.json.tmp");Directory.CreateDirectory(tmp);bool failed=false;try{DofusCompanion.Toggle(store,doc);}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}Directory.Delete(tmp);Check(failed&&DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count==1,"Retour arrière écriture échouée");store.Save();var empty=new CompanionWindow(new Store(Path.Combine(folder,"empty")),true);empty.Render(Path.Combine(folder,"welcome.png"));Check(Find<Button>(empty.Content as DependencyObject).Any(x=>Equals(x.Content,"Personnage · Guides")),"Configuration accessible sans guide");GanymedeTest(store,folder);AssociationTest(store,folder);var setupStore=new Store(Path.Combine(folder,"onboarding"));var setupCompanion=new CompanionWindow(setupStore,true);var setup=setupCompanion.OptionsPreview();CompanionWindow.RenderPreview(setup,Path.Combine(folder,"character-creation.png"));var fields=Find<TextBox>(setup.Content as DependencyObject).ToArray();Check(fields.Length>=2,"Champs personnage visibles");fields[0].Text="Nouveau personnage test";fields[1].Text="Serveur test";Find<Button>(setup.Content as DependencyObject).First(x=>Equals(x.Content,"Enregistrer et choisir un parcours →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(setupStore.Value.dofus.characters.Count==1&&new Store(setupStore.Root).Value.dofus.characters[0].name=="Nouveau personnage test","Création réelle et sauvegarde depuis le nouvel accueil");CompanionWindow.RenderPreview(setup,Path.Combine(folder,"guide-picker.png"));Check(Find<ComboBox>(setup.Content as DependencyObject).Any(x=>x.Items.Count>=2),"Sélection de guides disponible après création");var fontFace=new System.Windows.Media.Typeface(GuideAssets.TitleFont,System.Windows.FontStyles.Normal,System.Windows.FontWeights.Normal,System.Windows.FontStretches.Normal);System.Windows.Media.GlyphTypeface glyph;Check(fontFace.TryGetGlyphTypeface(out glyph)&&glyph.FontUri.ToString().Contains("fontbleach"),"Police Bleach embarquée réellement utilisée");Check(GuideAssets.Load("dofus-sylvestre").PixelWidth==128,"Icône Dofus embarquée");var preparedPortrait=CharacterPortraits.Prepare(Path.Combine(folder,"portraits/sample.webp"));string portraitKey=CharacterPortraits.Save(setupStore,preparedPortrait);PersonalWorkflows.Change(setupStore,()=>setupStore.Value.portraits[setupStore.Value.dofus.active]=portraitKey);var portraitOverlay=new CompanionWindow(new Store(setupStore.Root),true);portraitOverlay.Render(Path.Combine(folder,"portrait-widget.png"));Check(Find<Border>(portraitOverlay.Content as DependencyObject).Any(x=>x.Background is System.Windows.Media.ImageBrush),"Portrait réellement affiché sur le compagnon");portraitOverlay.Close();setupStore.Value.dofus.characters[0].guide="parcours-exemple";TougliReader.Cache(setupStore,"parcours-exemple",Sample);setupStore.Save();var fullPortrait=new CompanionWindow(setupStore,true);fullPortrait.Render(Path.Combine(folder,"portrait-fullbody.png"));Check(Find<Image>(fullPortrait.Content as DependencyObject).Any(x=>x.Source is System.Windows.Media.Imaging.BitmapSource && x.Stretch==System.Windows.Media.Stretch.Uniform),"Portrait entier affiché sans déformation");Check(Find<TextBlock>(fullPortrait.Content as DependencyObject).Any(x=>x.Text=="PARCOURS"),"Guide sans Dofus présenté sans faux objectif");fullPortrait.Close();GuideLibrary.Merge(setupStore,new System.Collections.Generic.List<TougliGuideInfo>{new TougliGuideInfo{Slug="dofus-ebene",Title="Quête Ébène fictive zzz test catalogue"}});Check(GuideLibrary.Filter(GuideLibrary.Read(new Store(setupStore.Root)),"ebene fictive zzz test catalogue",1).Count()==1,"Recherche du catalogue conservé sans accents");var libraryStore=new Store